  SectionRepository,
  WorkflowRepository,
  ProjectRepository,
  LogicRuleRepository,
  DocumentTemplateRepository,
  WorkflowTemplateRepository,
  DatavaultWritebackMappingsRepository
} from '../../../server/repositories';
// Mock repositories
vi.mock('../../../server/repositories', () => ({
