            type: "condition", id: "c1",
            variable: "age",
            operator: "greater_than",
            value: 65,
            valueType: "constant",
          },
        ],
      };

      const result = describeConditionExpression(expression);
      expect(result).toContain("OR");
    });

    it("should use variable labels when provided", () => {
      const expression: ConditionExpression = {
        type: "group", id: "g1",
        operator: "AND",
        conditions: [
          {
            type: "condition", id: "c1",
            variable: "step-uuid-123",
            operator: "equals",
            value: "test",
            valueType: "constant",
          },
        ],
      };

      const variableLabels = {
        "step-uuid-123": "First Name",
      };

      const result = describeConditionExpression(expression, variableLabels);
      expect(result).toContain("First Name");
    });

    it("should describe between operator", () => {
      const expression: ConditionExpression = {
        type: "group", id: "g1",
        operator: "AND",
        conditions: [
          {
            type: "condition", id: "c1",
            variable: "age",
            operator: "between",
            value: 18,
            value2: 65,
            valueType: "constant",
          },
        ],
      };

      const result = describeConditionExpression(expression);
      expect(result).toContain("is between");
      expect(result).toContain("18");
      expect(result).toContain("65");
    });

    it("should describe operators without values", () => {
      const operators: Array<"is_true" | "is_false" | "is_empty" | "is_not_empty"> = [
        "is_true",
        "is_false",
        "is_empty",
        "is_not_empty",
      ];

      operators.forEach((op) => {
        const expression: ConditionExpression = {
          type: "group", id: "g1",
          operator: "AND",
          conditions: [
            {
              type: "condition", id: "c1",
              variable: "value",
              operator: op,
              value: null,
              valueType: "constant",
            },
          ],
        };

        const result = describeConditionExpression(expression);
        expect(result).toContain("value");
        expect(result.length).toBeGreaterThan(0);
      });
    });

    it("should describe variable references", () => {
      const expression: ConditionExpression = {
        type: "group", id: "g1",
        operator: "AND",
        conditions: [
          {
            type: "condition", id: "c1",
            variable: "firstName",
            operator: "equals",
            value: "lastName",
            valueType: "variable",
          },
        ],
      };

      const variableLabels = {
        firstName: "First Name",
        lastName: "Last Name",
      };

      const result = describeConditionExpression(expression, variableLabels);
      expect(result).toContain("First Name");
      expect(result).toContain("Last Name");
    });

    it("should handle nested groups with parentheses", () => {
      const expression: ConditionExpression = {
        type: "group", id: "g1",
        operator: "AND",
        conditions: [
          {
            type: "group", id: "g1",
            operator: "OR",
            conditions: [
              {
                type: "condition", id: "c1",
                variable: "a",
                operator: "equals",
                value: 1,
                valueType: "constant",
              },
              {
                type: "condition", id: "c1",
                variable: "b",
                operator: "equals",
                value: 2,
                valueType: "constant",
              },
            ],
          },
        ],
      };

      const result = describeConditionExpression(expression);
      expect(result).toContain("(");
      expect(result).toContain(")");
      expect(result).toContain("OR");
    });

    it("should format array values", () => {
      const expression: ConditionExpression = {
        type: "group", id: "g1",
        operator: "AND",
        conditions: [
          {
            type: "condition", id: "c1",
            variable: "tags",
            operator: "includes_all",
            value: ["urgent", "important"],
            valueType: "constant",
          },
        ],
      };

      const result = describeConditionExpression(expression);
      expect(result).toContain("[");
      expect(result).toContain("]");
    });
  });
